namespace ghidra.graph.graphs;





using docking.widgets.label;
using generic.theme.GThemeDefaults.Colors;

/**
 * A test vertex that renders using a {@link JLabel}.
 */
public class LabelTestVertex : AbstractTestVertex {

	private JLabel label;

	public LabelTestVertex(string name) : base(name)
    {
	}

	/* @Override */
	public JComponent getComponent() {
		if (label == null) {
			label = new GDLabel();
			label.setText(getName());
			label.setPreferredSize(new Dimension(50, 50));
			label.setBackground(Palette.GOLD);
			label.setOpaque(true);
			label.setBorder(BorderFactory.createRaisedBevelBorder());
			label.setHorizontalAlignment(SwingConstants.CENTER);
		}
		return label;
	}

}
